// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from stackedNormalizedHorizontal ----
// Synthetic stand-in for the American Community Survey age-by-state table used by the
// source notebook. Shapes and spread are plausible; the numbers are not observations.

const AGE_GROUPS = ['<10', '10-19', '20-34', '35-49', '50-64', '≥65'] as const;

type AgeGroup = (typeof AGE_GROUPS)[number];
type StateAgeRow = { state: string; total: number } & { [K in AgeGroup]: number };

const STATES = [
  'Utah',
  'Texas',
  'Alaska',
  'Idaho',
  'Nebraska',
  'Georgia',
  'Illinois',
  'Nevada',
  'Colorado',
  'Ohio',
  'Oregon',
  'Arizona',
  'Delaware',
  'Montana',
  'Vermont',
  'Maine'
];

// National-ish baseline composition, then a per-state tilt that trades the oldest band
// against the youngest so the sorted rows read as one continuous gradient.
const BASE_SHARE = [0.122, 0.131, 0.203, 0.192, 0.194, 0.158];
const TILT = [1.0, 0.72, 0.28, -0.12, -0.62, -1.26];

function mulberry32(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function buildRows(): StateAgeRow[] {
  const random = mulberry32(20260813);
  return STATES.map((state) => {
    const tilt = random() * 2 - 1;
    const raw = BASE_SHARE.map(
      (share, k) => share * (1 + 0.42 * tilt * TILT[k]) * (0.94 + 0.12 * random())
    );
    const sum = raw.reduce((a, b) => a + b, 0);
    const total = Math.round(650_000 + random() ** 2 * 28_000_000);
    const row = { state, total } as StateAgeRow;
    AGE_GROUPS.forEach((group, k) => {
      row[group] = Math.round((total * raw[k]) / sum);
    });
    return row;
  });
}

const stateAgeRows = buildRows();

const MARGIN = { top: 34, right: 12, bottom: 54, left: 76 };
const LEGEND_SWATCH = 10;
const MIN_LEGEND_ITEM = 52;
/** A segment narrower than this cannot hold its own percentage, so the label is dropped. */
const MIN_SEGMENT_LABEL = 34;

const formatPercent = d3.format('.0%');
const formatCount = d3.format(',');

/** One row per state carrying a count for every age group, plus the groups to stack, youngest first. */
export type Data = { ageGroups: readonly AgeGroup[]; rows: StateAgeRow[] };

const DEMO: Data = { ageGroups: AGE_GROUPS, rows: stateAgeRows };

export default function StackedNormalizedHorizontalBar({
  data = DEMO,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.72);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  // Sorting by the youngest band's share is what makes the expanded stack legible:
  // every other band then shifts monotonically down the rows.
  const rows = useMemo(() => {
    const youngest = data.ageGroups[0];
    return [...data.rows].sort(
      (a, b) => b[youngest] / b.total - a[youngest] / a.total
    );
  }, [data]);

  const series = useMemo(
    () =>
      d3
        .stack<StateAgeRow, AgeGroup>()
        .keys(data.ageGroups)
        .value((d, key) => d[key])
        .offset(d3.stackOffsetExpand)(rows),
    [data, rows]
  );

  const x = useMemo(() => d3.scaleLinear().domain([0, 1]).range([0, innerWidth]), [innerWidth]);

  const y = useMemo(
    () =>
      d3
        .scaleBand<string>()
        .domain(rows.map((d) => d.state))
        .range([0, innerHeight])
        .padding(0.14),
    [rows, innerHeight]
  );

  const color = useMemo(
    () => d3.scaleOrdinal<AgeGroup, string>().domain(data.ageGroups).range(d3.schemeSpectral[6]),
    [data]
  );

  const xTicks: Tick[] = useMemo(
    () =>
      x
        .ticks(Math.max(2, Math.round(innerWidth / 90)))
        .map((v) => ({ value: formatPercent(v), offset: x(v) })),
    [x, innerWidth]
  );

  if (width === 0) return null;

  const legendItem = Math.min(110, innerWidth / data.ageGroups.length);
  const showLegendText = legendItem >= MIN_LEGEND_ITEM;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Normalized stacked horizontal bar chart of population share by age group for sixteen US states, each row summing to 100 percent and sorted by the share under age ten. Synthetic data from a seeded generator, not the American Community Survey."
    >
      <g transform={`translate(${MARGIN.left},14)`}>
        {data.ageGroups.map((group, i) => (
          <g key={group} transform={`translate(${i * legendItem},0)`}>
            <rect width={LEGEND_SWATCH} height={LEGEND_SWATCH} y={-LEGEND_SWATCH} fill={color(group)} />
            {showLegendText && (
              <text x={LEGEND_SWATCH + 5} fontSize={11} fill="var(--muted)">
                {group}
              </text>
            )}
          </g>
        ))}
      </g>

      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <g className="axis">
          {xTicks.map((t) => (
            <line key={t.value} className="grid" x1={t.offset} x2={t.offset} y1={0} y2={innerHeight} />
          ))}
        </g>

        {series.map((band) => (
          <g key={band.key} fill={color(band.key)}>
            {band.map((point) => {
              const row = point.data;
              const segmentWidth = x(point[1]) - x(point[0]);
              const top = y(row.state) ?? 0;
              return (
                <g key={row.state} transform={`translate(${x(point[0])},${top})`}>
                  <rect width={Math.max(segmentWidth, 0)} height={y.bandwidth()}>
                    <title>{`${row.state} · ${band.key}\n${formatCount(row[band.key])} (${formatPercent(
                      point[1] - point[0]
                    )})`}</title>
                  </rect>
                  {segmentWidth >= MIN_SEGMENT_LABEL && (
                    <text
                      x={segmentWidth / 2}
                      y={y.bandwidth() / 2}
                      dy="0.32em"
                      textAnchor="middle"
                      fontSize={10}
                      fill="var(--bg)"
                    >
                      {formatPercent(point[1] - point[0])}
                    </text>
                  )}
                </g>
              );
            })}
          </g>
        ))}

        {rows.map((row) => (
          <text
            key={row.state}
            x={-8}
            y={(y(row.state) ?? 0) + y.bandwidth() / 2}
            dy="0.32em"
            textAnchor="end"
            fontSize={11}
            fill="var(--text)"
          >
            {row.state}
          </text>
        ))}

        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
      </g>

      <text x={MARGIN.left} y={height - 8} fontSize={10} fill="var(--muted)">
        Synthetic data from a seeded generator, not the American Community Survey.
      </text>
    </svg>
  );
}
